// seedPlaybackItem seeds one plain item (id, one fresh library) so the
// playback verb tests exercise REAL store rows: the 6.3 pre-mint precheck
// resolves every playback request through the viewer-scoped GetItem before
// either closure runs, so an unseeded id now reads as hidden for every
// principal — the stub-closure tests seed the ids they expect to serve.
func seedPlaybackItem(t *testing.T, st *store.Store, id string) {
	t.Helper()
	ctx := context.Background()
	lib, err := st.CreateLibrary(ctx, "film", "/media/precheck", "Precheck")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	if err := st.PutItem(ctx, store.Item{
		ID: id, ModuleID: "film", LibraryID: lib, FileID: "fid_" + id,
		RelativePath: id + ".mkv", MediaType: "film",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

// TestPlaybackPrecheckHidden is the 6.3 acceptance: BOTH playback verbs
// resolve the item through a viewer-scoped GetItem BEFORE Deps.Playback/Play
// runs — a hidden item is 404 not_found with the closure never invoked (no
// descriptor, no media token, no enqueue — no mint on the hidden path), a
// granted item plays exactly as before, and the legacy principals (env-admin,
// unbound device) keep today's see-all posture.
func TestPlaybackPrecheckHidden(t *testing.T) {
	st := openAPIStore(t)
	ctx := context.Background()
	lib1, err := st.CreateLibrary(ctx, "tv", "/media/one", "One")
	if err != nil {
		t.Fatalf("CreateLibrary lib1: %v", err)
	}
	lib2, err := st.CreateLibrary(ctx, "film", "/media/two", "Two")
	if err != nil {
		t.Fatalf("CreateLibrary lib2: %v", err)
	}
	const granted = "itm_granted"
	const hidden = "itm_hidden"
	seedAt := func(id string, lib int64) {
		t.Helper()
		if err := st.PutItem(ctx, store.Item{
			ID: id, ModuleID: "tv", LibraryID: lib, FileID: "fid_" + id,
			RelativePath: id + ".mkv", MediaType: "tv",
			Document: json.RawMessage(`{}`), SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}
	seedAt(granted, lib1)
	seedAt(hidden, lib2)

	// The descriptor closure and the play stub both count their invocations —
	// the heart of the test is that a hidden request NEVER reaches either.
	pbCalls := 0
	pb := func(context.Context, string) (Playback, error) {
		pbCalls++
		return Playback{
			Mode:       "hls",
			State:      "complete",
			PlayURL:    "/media/item/index.m3u8?token=tok",
			Sections:   []map[string]any{{"kind": "chapter", "start": 0.0, "end": 5.5}},
			Voiceovers: []map[string]any{{"index": 0, "label": "Japanese"}},
			Token:      "fresh-media-token",
		}, nil
	}
	ps := &playStub{queued: true}

	precheckRouter := func(mws ...func(http.Handler) http.Handler) http.Handler {
		h := &app{deps: Deps{Store: st, Playback: pb, Play: ps.play()}}
		r := chi.NewRouter()
		for _, mw := range mws {
			r.Use(mw)
		}
		r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, h) })
		return r
	}

	t.Run("hidden_item_404s_and_never_mints", func(t *testing.T) {
		h := precheckRouter(principalInjector(RoleClient), principalViewerInjector(access.User(42, []int64{lib1}, nil)))
		// GET descriptor: the closure must never run — no descriptor, no
		// Set-Cookie media token on the wire.
		pbCalls = 0
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+hidden+"/playback", "", adminToken)
		if resp.StatusCode != http.StatusNotFound {
			resp.Body.Close()
			t.Fatalf("hidden GET status = %d, want 404", resp.StatusCode)
		}
		if eb := decodeError(t, resp); eb.Error.Code != "not_found" || eb.Error.Message != "item "+hidden+" not found" {
			t.Fatalf("hidden GET body = %+v, want the canonical item not-found floor", eb.Error)
		}
		resp.Body.Close()
		if ck := resp.Cookies(); len(ck) != 0 {
			t.Fatalf("hidden GET cookies = %v, want none — no media token may be minted", ck)
		}
		if pbCalls != 0 {
			t.Fatalf("descriptor closure ran %d times on the hidden path; the precheck must gate it", pbCalls)
		}
		// POST play: the mutation never runs either — hidden ≡ unknown, no
		// enqueue, no state touch.
		ps.calls = 0
		if resp := doRequest(t, h, http.MethodPost, "/api/v1/items/"+hidden+"/play", `{"retry":true}`, adminToken); resp.StatusCode != http.StatusNotFound {
			resp.Body.Close()
			t.Fatalf("hidden POST status = %d, want 404", resp.StatusCode)
		} else {
			resp.Body.Close()
		}
		if ps.calls != 0 {
			t.Fatalf("play closure ran %d times on the hidden path; the precheck must gate it", ps.calls)
		}
	})

	t.Run("visible_item_plays_unchanged", func(t *testing.T) {
		h := precheckRouter(principalInjector(RoleClient), principalViewerInjector(access.User(42, []int64{lib1}, nil)))
		pbCalls = 0
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+granted+"/playback", "", adminToken)
		if resp.StatusCode != http.StatusOK {
			resp.Body.Close()
			t.Fatalf("granted GET status = %d, want 200", resp.StatusCode)
		}
		var d playbackResponse
		if err := json.NewDecoder(resp.Body).Decode(&d); err != nil {
			t.Fatalf("decode descriptor: %v", err)
		}
		resp.Body.Close()
		if d.Mode != "hls" || d.State != "complete" || len(d.Sections) != 1 || len(d.Voiceovers) != 1 {
			t.Fatalf("descriptor = %+v, want today's shape carried through", d)
		}
		ck := resp.Cookies()
		if len(ck) != 1 || ck[0].Name != mediaCookieName || ck[0].Value != "fresh-media-token" {
			t.Fatalf("cookies = %v, want the minted media_token cookie (visible items mint as today)", ck)
		}
		if pbCalls != 1 {
			t.Fatalf("descriptor closure ran %d times on the visible path, want exactly 1", pbCalls)
		}
		// POST play: the mutation runs and answers today's shape.
		ps.calls = 0
		resp = doRequest(t, h, http.MethodPost, "/api/v1/items/"+granted+"/play", `{"retry":true}`, adminToken)
		if resp.StatusCode != http.StatusAccepted {
			resp.Body.Close()
			t.Fatalf("granted POST status = %d, want 202", resp.StatusCode)
		}
		if ps.calls != 1 || !ps.retry || ps.itemID != granted {
			t.Fatalf("play calls = %+v, want exactly one retry call for %s", ps, granted)
		}
		var body struct {
			Queued bool `json:"queued"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
			t.Fatalf("decode play response: %v", err)
		}
		resp.Body.Close()
		if !body.Queued {
			t.Fatal("granted POST body.queued = false, want true")
		}
	})

	t.Run("env_admin_keeps_legacy_see_all", func(t *testing.T) {
		h := precheckRouter(principalInjector(RoleAdmin))
		// Both items resolve for the env-admin (Admin scope sees all) — the
		// precheck changes nothing for the legacy principal.
		for _, id := range []string{granted, hidden} {
			pbCalls = 0
			resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+id+"/playback", "", adminToken)
			if resp.StatusCode != http.StatusOK {
				resp.Body.Close()
				t.Fatalf("admin GET %s status = %d, want 200", id, resp.StatusCode)
			}
			resp.Body.Close()
			if pbCalls != 1 {
				t.Fatalf("admin GET %s: descriptor closure ran %d times, want 1", id, pbCalls)
			}
			if resp := doRequest(t, h, http.MethodPost, "/api/v1/items/"+id+"/play", `{"retry":true}`, adminToken); resp.StatusCode != http.StatusAccepted {
				resp.Body.Close()
				t.Fatalf("admin POST %s status = %d, want 202", id, resp.StatusCode)
			} else {
				resp.Body.Close()
			}
		}
	})

	t.Run("unbound_device_keeps_legacy_see_all", func(t *testing.T) {
		// RoleClient with NO injected viewer: viewerFor lands on the
		// LegacyDevice scope (nil Identity, no binding yet) — today's explicit
		// see-all, so the other library's item still plays.
		h := precheckRouter(principalInjector(RoleClient))
		for _, id := range []string{granted, hidden} {
			pbCalls = 0
			resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+id+"/playback", "", adminToken)
			if resp.StatusCode != http.StatusOK {
				resp.Body.Close()
				t.Fatalf("device GET %s status = %d, want 200", id, resp.StatusCode)
			}
			resp.Body.Close()
			if pbCalls != 1 {
				t.Fatalf("device GET %s: descriptor closure ran %d times, want 1", id, pbCalls)
			}
		}
	})
}
